import json,hashlib
from pathlib import Path
b=Path('docs/experiments/r6-robustness-auto'); repair=json.loads((b/'CPU_LEGACY_RECONCILIATION_REPAIR_V2.json').read_text()); s=json.loads((b/'LEGACY_MODEL_SESSION_SUPPLEMENT.json').read_text()); p=json.loads((b/'LEGACY_MODEL_CLEANUP_RECONCILIATION_PROPOSAL_V2.json').read_text())
def check(x):
 if isinstance(x,dict):
  if set(x)>={'path','sha256'}:
   f=Path(x['path']); h=hashlib.sha256(f.read_bytes()).hexdigest(); print('PIN',h==x['sha256'],str(f),h)
  else:
   for v in x.values():check(v)
 elif isinstance(x,list):
  for v in x:check(v)
check(repair);check(s)
for r in p['events']:
 for k in ['original_receipt','original_events','original_stderr','original_last_message']:check(r[k])
 print('RECEIPT',Path(r['original_receipt']['path']).read_text());print('LAST',Path(r['original_last_message']['path']).read_text())
raw=Path(s['session_source']['path']).read_text().splitlines()
for i,line in enumerate(raw,1):
 r=json.loads(line)
 if r['type']=='session_meta' or r.get('payload',{}).get('type') not in ('message',) and r['type']=='response_item':print('RAW',i,line)
for t in s['tool_calls']:
 for kind in ['call','output']:
  line=raw[t[kind+'_line']-1];print('RECORD_HASH',kind,hashlib.sha256(line.encode()).hexdigest()==t[kind+'_record_sha256'])
print('FIRST_CLI',Path(s['original_events']['path']).read_text())
print('STATE', (b/'batch/state.json').read_text());print('BUDGET',(b/'goal_budget.json').read_text())
PY"

